const React = require('react');
if (!React.useActionState) {
  React.useActionState = function(fn, init) { return [init, fn, false]; };
}
const { ContactForm } = require('./components/ContactForm.js');
const form = ContactForm({ action: async (prev, formData) => ({ ok: true }) });
if (!form || form.state !== null || typeof form.formAction !== 'function') {
  console.error('Assertion failed');
  process.exit(1);
}
console.log('REACT_19_USE_ACTION_STATE_VERIFIED');
process.exit(0);

